Por eso este correo NO ha pasado por el clasificador ni por el RAG de estatutos (compuerta de confidencialidad): sin comunidad_id no hay filtro posible, y no se puede garantizar el aislamiento entre fincas.

Si se ha registrado en la tabla de incidencias, con comunidad_id vacio, imputacion 'mixto' y decidido_por 'compuerta', y esta en la cola de revision: no clasificar no puede significar no dejar rastro. Revisar y dar de alta a mano si corresponde.

Remitente: {{ $('IMAP Email Trigger').first().json.from }}
Asunto: {{ $('IMAP Email Trigger').first().json.subject }}

Cuerpo:
{{ $('IMAP Email Trigger').first().json.textPlain }}

parameters.jsCode:
const CONFIANZA_MAX_CON_RIVAL = 0.6;
const IMPUTACIONES_VALIDAS = ['comun', 'privativo', 'mixto', 'no_aplica'];

return $input.all().map((item, i) => {
  let raw = item.json.output;
  if (typeof raw === 'string') {
    const match = raw.match(/\{[\s\S]*\}/);
    try {
      raw = JSON.parse(match ? match[0] : raw);
    } catch (e) {
      raw = null;
    }
  }
  // El agente a veces devuelve el objeto anidado como {"output": {...}} en vez de plano
  // (visto en ejecuciones reales cuando el autoFix del parser reintenta). Desenvuelve antes
  // de validar, si no 'imputacion' vive en raw.output.imputacion y el chequeo de abajo lo
  // trata como ausente.
  if (raw && typeof raw === 'object' && raw.output && typeof raw.output === 'object') {
    raw = raw.output;
  }
  // Un objeto bien formado pero con forma equivocada (imputacion ausente o fuera del
  // vocabulario cerrado) no dispara el chequeo '!raw' de abajo — sin esto, 'undefined'
  // se cuela tal cual en el insert de Postgres en vez de caer a sin_clasificar.
  if (raw && !IMPUTACIONES_VALIDAS.includes(raw.imputacion)) {
    raw = null;
  }
  // Si el agente no devuelve salida utilizable (modelo caido, JSON irrecuperable), esto lanzaba
  // 'Cannot read properties of undefined' y la incidencia no llegaba a ninguna tabla. Como el
  // trigger IMAP marca el correo como leido ANTES de ejecutar, el caso se perdia entero: paso
  // con i21. Ahora entra etiquetado como sin_clasificar, con confianza 0, que el umbral manda a
  // revision. Peor una fila fea en la cola que un correo que nadie sabe que existio.
  if (!raw || typeof raw !== 'object') {
    raw = {
      imputacion: 'sin_clasificar',
      imputacion_rival: 'ninguna',
      elemento_normalizado: null,
      fundamento: [],
      urgencia: false,
      requiere_junta: false,
      plazos_activos: [],
      confianza: 0,
    };
  }

  // Normaliza confianza: si el modelo no la devuelve o no es numérica, fuerza 0. 0 siempre
  // dispara revisión humana vía el umbral; nunca cuela la incidencia sin control.
  let confianza = raw.confianza;
  confianza = (typeof confianza === 'number' && Number.isFinite(confianza)) ? confianza : 0;

  const imputacion = raw.imputacion;

  // Recorte por rival: si el modelo reconoce una segunda imputación defendible, su propia
  // confianza no puede pasar de aquí. La confianza verbalizada de un LLM satura cerca de 1
  // (medido en la Demo A: 27 de 28 casos en [0.9-1.0], los 4 errores incluidos), así que el
  // umbral solo protege si algo la baja de forma determinista, no si el modelo se siente seguro.
  const rival = typeof raw.imputacion_rival === 'string' ? raw.imputacion_rival : 'ninguna';
  const hay_rival = rival !== 'ninguna' && rival !== imputacion;
  if (hay_rival) confianza = Math.min(confianza, CONFIANZA_MAX_CON_RIVAL);

  // Regla dura de la rúbrica (§6): si el fundamento sale de una cláusula de la escritura de
  // ESTA finca, el sistema no cierra el caso — lo firma un humano. Lo que NO hace es tocar la
  // imputación: medido sobre las 45 incidencias, forzar 'mixto' aquí destruía 6 clasificaciones
  // correctas (i07, i13, i20, i26, i28, i33) y bajaba el acierto del 23.8% al 15.6%. Citar la
  // escritura no significa que el reparto sea mixto, solo que la respuesta depende de un
  // documento propio de la finca y nadie debería mandarla sin leerla.
  const fundamento = Array.isArray(raw.fundamento) ? raw.fundamento : [];
  const depende_de_estatutos = fundamento.some((f) => f && f.fuente === 'estatutos');

  const plazos_activos = Array.isArray(raw.plazos_activos) ? raw.plazos_activos : [];
  const sin_plazo = plazos_activos.length === 0;

  // Umbral asimétrico (regla 2 del brief): en esta demo la rama "sin rastro" no es ninguna
  // imputación, es declarar plazos_activos: []. Un plazo del art. 16 LCS perdido no se
  // recupera después, así que exige más confianza (0.9) que el resto de casos (0.7). Si la
  // env var no está definida o no es numérica, Number(...) da NaN y NaN >= NaN es false:
  // falla cerrado a revisión humana, nunca cuela sin control.
  const umbral = sin_plazo
    ? Number($env.FINCAS_UMBRAL_SIN_PLAZO)
    : Number($env.FINCAS_CONFIANZA_UMBRAL);

  const confianza_ok = confianza >= umbral;

  // accion: el umbral manda primero (si no se alcanza, todo va a revisión con independencia
  // de la imputación). Con confianza suficiente, mixto también va a revisión (regla 3 del
  // brief: dependencia estatutaria o reparto de causa exige lectura humana aunque el modelo
  // esté seguro). accion es descriptivo (queda en la fila, para email/auditoría); quien de
  // verdad enruta la ejecución es 'Switch Imputación' leyendo imputacion, no este campo. Por
  // eso ese Switch tiene su propio fallbackOutput: 'extra' hacia la cola de revisión, para
  // que un valor de imputacion no reconocido no se quede sin ninguna salida conectada.
  let accion;
  if (!confianza_ok) {
    accion = 'revision_administrador';
  } else if (depende_de_estatutos) {
    accion = 'revision_administrador';
  } else if (imputacion === 'mixto') {
    accion = 'revision_administrador';
  } else if (imputacion === 'comun') {
    accion = 'parte_proveedor';
  } else if (imputacion === 'privativo') {
    accion = 'borrador_respuesta_vecino';
  } else {
    accion = 'revision_administrador';
  }

  // La vía deja claro QUÉ mandó el caso a un humano: su propia inseguridad (umbral), la
  // regla estatutaria (estatutos), o nadie (sistema). Si el modelo ya dudaba, eso manda.
  const decidido_por = !confianza_ok ? 'umbral' : (depende_de_estatutos ? 'estatutos' : 'sistema');

  return {
    json: {
      ...raw,
      imputacion_rival: rival,
      plazos_activos,
      confianza,
      umbral_aplicado: umbral,
      accion,
      decidido_por,
    },
    pairedItem: { item: i },
  };
});

// Expande plazos_activos (0..N valores) en 0..N items, uno por plazo a dar de alta. Si el
// array viene vacio no se emite ningun item y la rama de plazos no hace nada aguas abajo:
// no hace falta un IF explicito para "si no esta vacio" (rubrica seccion 5: cuando dos ejes
// no compiten por el mismo dato, cada uno se resuelve con su propio criterio, sin bloquear
// al otro).
//
// Solo existe un tipo de plazo implementado en el esquema actual (siniestro_lcs16, 7 dias -
// ver init-fincas-tables.sql). DEFAULT_DIAS es un colchon defensivo por si el clasificador
// devuelve algun dia un codigo de plazo que esta rubrica todavia no cubre: mejor una fecha
// visible y revisable que ningun aviso.
const DIAS_POR_TIPO = { siniestro_lcs16: 7 };
const DEFAULT_DIAS = 30;

const toDateStr = (d) => d.toISOString().slice(0, 10);

const out = [];
$input.all().forEach((item, idx) => {
  const plazos = Array.isArray(item.json.plazos_activos) ? item.json.plazos_activos : [];
  for (const tipo of plazos) {
    const dias = DIAS_POR_TIPO[tipo] ?? DEFAULT_DIAS;
    const inicio = new Date();
    const vence = new Date(inicio);
    vence.setDate(vence.getDate() + dias);
    out.push({
      json: {
        incidencia_id: item.json.id,
        comunidad_id: item.json.comunidad_id,
        elemento_normalizado: item.json.elemento_normalizado,
        tipo,
        dias_plazo: dias,
        inicio: toDateStr(inicio),
        vence: toDateStr(vence),
      },
      pairedItem: { item: idx },
    });
  }
});
return out;

