// La busqueda devuelve un item por fragmento. El agente tiene que ejecutarse una vez por
// correo, no una vez por fragmento, asi que aqui se juntan en uno solo.
const frags = $input.all().map((it) => it.json.document).filter((d) => d && d.pageContent);

// Si la busqueda no devuelve nada (comunidad sin escritura cargada, o filtro que no casa),
// el agente tiene que saberlo explicitamente: si no, se inventa que ha leido una clausula.
const texto = frags.length
  ? frags
      .map((d, i) => `[fragmento ${i + 1} | pagina ${d.metadata?.pagina ?? '?'}]\n${d.pageContent.trim()}`)
      .join('\n\n')
  : 'SIN FRAGMENTOS: no hay ninguna clausula cargada para esta comunidad. Clasifica por el regimen legal y no cites estatutos.';

return [{ json: { estatutos: texto, fragmentos_estatutos: frags.length }, pairedItem: { item: 0 } }];
